{
  "name": "HP 3456A 六位半台式数字万用表",
  "name_en": "HP 3456A 6.5-digit Bench Multimeter",
  "manufacturer": "Hewlett-Packard",
  "description": "这是一台六位半台式数字万用表，用于高精度直流/交流电压、电阻和比值测量，支持二线/四线电阻以及统计、dB/dBm、相对值等数学功能，常用于电子测试、器件表征和校准实验。",
  "description_en": "A 6.5-digit bench digital multimeter for precision DC/AC voltage, resistance, and ratio measurements. It supports 2-wire/4-wire resistance and built-in math functions such as statistics, dB/dBm, and relative measurements, making it suitable for electronics testing, device characterization, and calibration work.",
  "tag_hints": [
    "6.5-digit multimeter",
    "bench DMM",
    "precision voltage measurement",
    "2-wire and 4-wire resistance",
    "ratio measurement",
    "statistics and math functions",
    "electrical test and calibration",
    "HPIB/GPIB instrument"
  ],
  "actions": [
    {
      "action_name": "auto-auto_range",
      "description": "将输入量程设为自动量程。",
      "description_en": "Set the input range to auto-ranging."
    },
    {
      "action_name": "auto-autozero",
      "description": "获取/设置自动调零功能。",
      "description_en": "Get/set the autozero setting."
    },
    {
      "action_name": "auto-delay",
      "description": "获取/设置触发后等待输入稳定的延时。",
      "description_en": "Get/set the delay after a trigger for the input to settle."
    },
    {
      "action_name": "auto-fetch",
      "description": "读取一次测量序列返回的读数。",
      "description_en": "Fetch the readings returned from a measurement sequence."
    },
    {
      "action_name": "auto-filter",
      "description": "获取/设置滤波设置。",
      "description_en": "Get/set the filter setting."
    },
    {
      "action_name": "auto-input_range",
      "description": "获取/设置输入量程。",
      "description_en": "Get/set the input range."
    },
    {
      "action_name": "auto-lower",
      "description": "获取/设置下限值。",
      "description_en": "Get/set the lower limit value."
    },
    {
      "action_name": "auto-math_mode",
      "description": "获取/设置数学运算模式。",
      "description_en": "Get/set the math mode."
    },
    {
      "action_name": "auto-measure",
      "description": "按当前设置执行一次测量。",
      "description_en": "Perform a one-time measurement using the current settings."
    },
    {
      "action_name": "auto-mode",
      "description": "获取/设置测量模式。",
      "description_en": "Get/set the measurement mode."
    },
    {
      "action_name": "auto-nplc",
      "description": "获取/设置每次测量的电源线周期积分时间。",
      "description_en": "Get/set the number of power-line cycles integrated per measurement."
    },
    {
      "action_name": "auto-number_of_digits",
      "description": "获取/设置测量位数。",
      "description_en": "Get/set the number of digits used in measurements."
    },
    {
      "action_name": "auto-number_of_readings",
      "description": "获取/设置每次触发/测量周期的读数次数。",
      "description_en": "Get/set the number of readings per trigger/measurement cycle."
    },
    {
      "action_name": "auto-r",
      "description": "获取/设置 R 参数值（用于 dBm 模式或读数存储）。",
      "description_en": "Get/set the R parameter value used for dBm mode or reading storage."
    },
    {
      "action_name": "auto-relative",
      "description": "获取/设置相对值（Null）模式。",
      "description_en": "Get/set the relative (null) mode."
    },
    {
      "action_name": "auto-trigger",
      "description": "发送一次手动触发信号。",
      "description_en": "Send a single manual trigger event."
    },
    {
      "action_name": "auto-trigger_mode",
      "description": "获取/设置触发模式。",
      "description_en": "Get/set the trigger mode."
    },
    {
      "action_name": "auto-upper",
      "description": "获取/设置上限值。",
      "description_en": "Get/set the upper limit value."
    },
    {
      "action_name": "auto-y",
      "description": "获取/设置用于缩放或百分比计算的 Y 值。",
      "description_en": "Get/set the Y value used in scale or percent calculations."
    },
    {
      "action_name": "auto-z",
      "description": "获取/设置用于缩放计算的 Z 值或统计模式下的第一笔读数。",
      "description_en": "Get/set the Z value used in scale calculations or the first reading in statistics mode."
    },
    {
      "action_name": "auto-mean",
      "description": "获取统计模式下测量结果的平均值。",
      "description_en": "Get the mean of measurements in statistics mode."
    },
    {
      "action_name": "auto-variance",
      "description": "获取统计模式下测量结果的方差。",
      "description_en": "Get the variance of measurements in statistics mode."
    },
    {
      "action_name": "auto-count",
      "description": "获取统计模式下已采集的测量次数。",
      "description_en": "Get the number of measurements acquired in statistics mode."
    }
  ]
}

